// Define a small interface
type Stringer interface {
    String() string
}

// This type satisfies Stringer automatically
type User struct {
    Name  string
    Email string
}

func (u User) String() string {
    return fmt.Sprintf("%s <%s>", u.Name, u.Email)
}

// Works with any Stringer — no coupling
func PrintAll(items []Stringer) {
    for _, item := range items {
        fmt.Println(item.String())
    }
}

// User satisfies Stringer without knowing about it
func main() {
    u := User{Name: "Alice", Email: "alice@example.com"}
    fmt.Println(u)  // calls String() automatically
}

// Interface defined by the consumer, not the provider
type UserStore interface {
    GetUser(id int) (*User, error)
    SaveUser(u *User) error
}

// Service accepts interface — easy to test
type UserService struct {
    store UserStore
}

func NewUserService(store UserStore) *UserService {
    return &UserService{store: store}
}

func (s *UserService) Rename(id int, name string) error {
    user, err := s.store.GetUser(id)
    if err != nil {
        return err
    }
    user.Name = name
    return s.store.SaveUser(user)
}

// In tests — pass a mock
type mockStore struct {
    users map[int]*User
}
func (m *mockStore) GetUser(id int) (*User, error) {
    return m.users[id], nil
}
func (m *mockStore) SaveUser(u *User) error {
    m.users[u.ID] = u; return nil
}

// Type assertion — extract concrete type
var val any = "hello"

str, ok := val.(string)
if ok {
    fmt.Println("String:", str)
}

// Type switch — branch on type
func describe(val any) string {
    switch v := val.(type) {
    case int:
        return fmt.Sprintf("integer: %d", v)
    case string:
        return fmt.Sprintf("string: %q", v)
    case bool:
        return fmt.Sprintf("boolean: %t", v)
    default:
        return fmt.Sprintf("unknown: %v", v)
    }
}

// With generics (Go 1.18+) — prefer over interface{}
func Max[T constraints.Ordered](a, b T) T {
    if a > b {
        return a
    }
    return b
}
